candidate_patch.text:
diff --git a/arch/powerpc/kernel/ptrace/ptrace-fpu.c b/arch/powerpc/kernel/ptrace/ptrace-fpu.c
index 5dca19361316..dadd6fd35280 100644
--- a/arch/powerpc/kernel/ptrace/ptrace-fpu.c
+++ b/arch/powerpc/kernel/ptrace/ptrace-fpu.c
@@ -18,7 +18,13 @@ int ptrace_get_fpr(struct task_struct *child, int index, unsigned long *data)
 #ifdef CONFIG_PPC_FPU_REGS
 	flush_fp_to_thread(child);
 	if (fpidx < (PT_FPSCR - PT_FPR0))
-		memcpy(data, &child->thread.TS_FPR(fpidx), sizeof(long));
+		if (IS_ENABLED(CONFIG_PPC32)) {
+			// On 32-bit the index we are passed refers to 32-bit words
+			*data = ((u32 *)child->thread.fp_state.fpr)[fpidx];
+		} else {
+			memcpy(data, &child->thread.TS_FPR(fpidx),
+			       sizeof(long));
+		}
 	else
 		*data = child->thread.fp_state.fpscr;
 #else
@@ -40,7 +46,13 @@ int ptrace_put_fpr(struct task_struct *child, int index, unsigned long data)
 #ifdef CONFIG_PPC_FPU_REGS
 	flush_fp_to_thread(child);
 	if (fpidx < (PT_FPSCR - PT_FPR0))
-		memcpy(&child->thread.TS_FPR(fpidx), &data, sizeof(long));
+		if (IS_ENABLED(CONFIG_PPC32)) {
+			// On 32-bit the index we are passed refers to 32-bit words
+			((u32 *)child->thread.fp_state.fpr)[fpidx] = data;
+		} else {
+			memcpy(&child->thread.TS_FPR(fpidx), &data,
+			       sizeof(long));
+		}
 	else
 		child->thread.fp_state.fpscr = data;
 #endif
